import React from "react"
import { ArrowRightIcon, LockIcon } from "@phosphor-icons/react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { IconTile } from "@/components/atoms/display/IconTile"
import { PriceTagProminent, type PriceBreakdown } from "@/components/blocks/commerce/PriceTag"
// The NON-legacy version (`designs/commerce/…`) — the `_legacy` version of the same
// name still exists but is a dead end; screens are forbidden from touching `_legacy`
// so every link in the chain has to move off it.
import { PhaseScarcityNote } from "@/components/blocks/commerce/PhaseScarcityNote"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { TitledText } from "@/components/composites/text/TitledText"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { StackH, StackV } from "@/components/frames/Stack"
import type { QueryCoursePricePreviewData } from "@/modules/api/graphql/queries/types/course-price-preview"

/** Props for {@link _TrialConversionStrip} — presentational; all text + price resolved, no fetch/store/i18n. */
export interface TrialConversionStripProps {
    /** Card title (already localized). */
    title: string
    /** Supporting line under the title — the connected file already picked the goal-gradient vs generic copy. */
    description: string
    /** Enroll CTA label (already localized). */
    cta: string
    /** Resolved pre-checkout price; omitted/null → the price line is skipped. */
    price?: QueryCoursePricePreviewData | null
    /**
     * `true` while the price is still fetching → the price column shimmers instead of
     * showing an empty gap, KEEPING its line boxes so nothing jumps in layout. The
     * header (icon/title/description) and the CTA never depend on the price fetch, so
     * they always render their real content.
     */
    isSkeleton?: boolean
    /** Open the shared payment modal in the course-enroll flow. */
    onEnroll: () => void
}

/**
 * Trial → enroll conversion strip on the content-home — the presentational half of
 * {@link import("./index").TrialConversionStrip}. Three honest levers: (1) loss-aversion copy,
 * (2) real pricing-phase scarcity via {@link PhaseScarcityNote}, (3) an outcome-framed enroll CTA.
 * Every number is handed in resolved — nothing fabricated. See `design/storybook/architecture/split.md`.
 *
 * @param props - {@link TrialConversionStripProps}
 */
export const _TrialConversionStrip = ({
    title,
    description,
    cta,
    price,
    isSkeleton = false,
    onEnroll,
}: TrialConversionStripProps) => {
    const breakdown: PriceBreakdown | undefined = price
        ? {
            phase: price.phasePriceVnd,
            loyaltyPercent: price.discountPercent,
        }
        : undefined

    // Header never rests — title/description already arrived as resolved strings
    // (i18n + the outline), not a fetch, so there is nothing here to shimmer.
    const headerRow = (
        <StackH gap={4} principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            align="center" items={[
                () => <IconTile icon={LockIcon} tone="accent" size="sm" />,
                () => <TitledText classNames={["flex-1"]} title={title} subtitle={description} />,
            ]} />
    )

    // The scarcity line is a CAPTION OF THE PRICE — price + scarcity are one cluster,
    // this is an intra-cluster seam (not the wider seam around the whole card).
    const priceColumn = (
        <StackV gap={4} isSkeleton={isSkeleton} items={
            isSkeleton && !price ? [
                // The header + CTA render instantly, but the price is a second fetch —
                // mirror the price line instead of showing an empty gap until it lands.
                () => <Typography size="h4" isSkeleton classNames={["w-1/3"]} />,
                () => <Typography size="xs" isSkeleton />,
            ] : price?.discountedPriceVnd != null ? [
                ({ isSkeleton }: SkeletonProps) => (
                    <PriceTagProminent
                        isSkeleton={isSkeleton}
                        discounted={price.discountedPriceVnd}
                        original={price.originalPriceVnd}
                        breakdown={breakdown}
                    />
                ),
                ({ isSkeleton }: SkeletonProps) => (
                    <PhaseScarcityNote
                        isSkeleton={isSkeleton}
                        currentPhase={price.currentPhase}
                        seatsRemaining={price.seatsRemainingInCurrentPhase}
                        nextPhasePriceVnd={price.nextPhasePriceVnd}
                    />
                ),
            ] : []
        } />
    )

    // Price is a NUMBER — shrinking it means nothing, unlike a long title that can
    // truncate. The row wraps when tight (`StackH`): the button drops to the next
    // line instead of the price getting squeezed.
    const footerRow = (
        <StackH gap={6} principle="block-boundary"
            explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
            align="end" justify="between" at="sm" items={[
                () => priceColumn,
                // ATOM `Button`, NOT the legacy HeroUI one — `suffixIcon` takes a COMPONENT
                // REF, the atom forces scale + weight; the CTA is never gated on the price
                // fetch, so it does not take `isSkeleton`.
                () => (
                    <Button
                        variant="primary"
                        size="lg"
                        label={cta}
                        suffixIcon={ArrowRightIcon}
                        iconSlide
                        onPress={onEnroll}
                    />
                ),
            ]} />
    )

    return (
        // The frame owns radius/shadow/padding from ONE source: `SurfaceCard`.
        <SurfaceCard identity={{ tier: "block", component: "TrialConversionStrip" }}
            body={() => (
                <StackV gap={6} items={[
                    () => headerRow,
                    () => footerRow,
                ]} />
            )}
        />
    )
}

import React from "react"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import {
    BookOpenIcon,
    CardsIcon,
    CodeIcon,
    FlagIcon,
    FlameIcon,
    PuzzlePieceIcon,
    type Icon as PhosphorIcon,
} from "@phosphor-icons/react"
import { AsyncContent } from "@/components/composites/async/AsyncContent"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { StatGridCard, type StatGridCardItem } from "@/components/composites/stats/StatGridCard"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * BLOCK — `WeeklyGoals`: "Weekly Goals" — the composite summary + six-metric
 * breakdown. See the component's own file header for the full contract; this
 * file only adds the states.
 *
 * 📐 LEAF by STRUCTURE (§14d.2): the six metrics never change the SHAPE of the
 * tree, only the numbers inside it, so this block has exactly ONE leaf
 * ("Content") — loading / error / content are states of that one leaf, the
 * same shape `ChallengeScoreCard`'s single leaf uses. No `isEmpty` state:
 * `items` is always the fixed six-metric set (see the component file header).
 */

/** The six weekly metrics this block always renders, in display order (mirrors backend `KpiKey`). */
export type WeeklyGoalKey = "lessons" | "studyDays" | "challenges" | "coding" | "flashcards" | "milestones"

/** One weekly-goal metric: current-week value vs the effective target, plus its coin reward. */
export interface WeeklyGoalItem {
    /** Which metric this row is. */
    key: WeeklyGoalKey
    /** Already-localized metric name (e.g. "Lessons") — screen copy, not owned by this block. */
    label: string
    /** The current-week value. */
    current: number
    /** The learner's custom weekly target; `null` when none set (the block falls back to a sensible default). */
    target: number | null
    /** Coin reward for claiming this metric this week; `null` when no target is set server-side. */
    coinReward: number | null
    /** `true` → this metric's reward can be claimed right now (met + not yet claimed). */
    canClaim: boolean
}

/** The viewer's weekly-goals snapshot (real shape of `myKpis`). */
export interface WeeklyGoalsData {
    /** All six metrics, in display order. */
    items: Array<WeeklyGoalItem>
    /** Server-computed composite score across every metric — read straight, never recomputed. */
    composite: {
        /** Average completion across the six metrics, 0–100. */
        percent: number
        /** Number of metrics already met (current >= effective target). */
        completed: number
        /** Always 6 — the fixed metric count. */
        total: number
    }
    /** Already-worded countdown to the weekly reset (e.g. "3 days 12 hours left"). Omit while unknown. */
    resetInLabel?: string
}

/** Props for {@link WeeklyGoals}. */
export interface WeeklyGoalsProps {
    /** True while the first load is running — {@link AsyncContent}'s loading branch. */
    isLoading: boolean
    /** Truthy → the snapshot failed to load. Pass SWR's `error`. */
    error?: unknown
    /** Retry handler for the error branch. */
    onRetry: () => void
    /** The viewer's weekly-goals snapshot. Required once loaded (no error). */
    data?: WeeklyGoalsData
    /** Sensible default target per metric, used when a metric has no custom `target` set yet. */
    defaultTargets: Record<WeeklyGoalKey, number>
    /** `true` → every atom this block owns switches to its own shimmer (data already loaded). */
    isSkeleton?: boolean
}

/** Phosphor icon per metric key — a pure display constant, decoupled from any editor's own map. */
const KPI_ICON: Record<WeeklyGoalKey, PhosphorIcon> = {
    lessons: BookOpenIcon,
    studyDays: FlameIcon,
    challenges: PuzzlePieceIcon,
    coding: CodeIcon,
    flashcards: CardsIcon,
    milestones: FlagIcon,
}

/** One metric cell's content: icon + label + ratio row, then the meter, then an optional coin hint. */
const goalCellContent = (
    item: WeeklyGoalItem,
    defaultTargets: Record<WeeklyGoalKey, number>,
    isSkeleton: boolean,
) => {
    const Icon = KPI_ICON[item.key]
    const effectiveTarget = item.target ?? defaultTargets[item.key]

    const iconLabel = (
        <StackH gap={2} isSkeleton={isSkeleton} items={[
            () => (isSkeleton ? (
                <Skeleton
                    className="size-5 shrink-0 rounded-full"

                />
            ) : (
                <Icon aria-hidden focusable="false" className="size-5 shrink-0 text-muted" />
            )),
            () => (
                <Typography
                    size="sm"
                    isSkeleton={isSkeleton}
                    text={item.label}

                />
            ),
        ]} />
    )

    const labelRow = (
        <StackH gap={3} principle="sibling-stack"
            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
            justify="between" isSkeleton={isSkeleton} items={[
                () => iconLabel,
                () => (
                    <Typography
                        size="xs"
                        color="muted"
                        tabularNums
                        isSkeleton={isSkeleton}
                        text={isSkeleton ? undefined : `${item.current}/${effectiveTarget}`}

                    />
                ),
            ]} />
    )

    return (
        <StackV gap={3} isSkeleton={isSkeleton} items={[
            () => labelRow,
            () => (
                <ProgressMeter
                    value={item.current}
                    max={effectiveTarget > 0 ? effectiveTarget : 1}
                    isSkeleton={isSkeleton}
                />
            ),
            ...(!isSkeleton && item.coinReward != null ? [() => (
                <Typography
                    size="xs"
                    color={item.canClaim ? "accent" : "muted"}
                    isSkeleton={isSkeleton}
                    text={`+${item.coinReward} coins when met`}

                />
            )] : []),
        ]} />
    )
}

/** Fixed-shape placeholder rendered while {@link WeeklyGoalsProps.isLoading} — six empty cells, no real data yet. */
const loadingItems = (defaultTargets: Record<WeeklyGoalKey, number>): Array<WeeklyGoalItem> =>
    (Object.keys(defaultTargets) as Array<WeeklyGoalKey>).map((key) => ({
        key,
        label: "",
        current: 0,
        target: null,
        coinReward: null,
        canClaim: false,
    }))

/** Props for the internal {@link Content} tree — reused for both the real render and the loading skeleton. */
interface ContentProps {
    items: Array<WeeklyGoalItem>
    composite: WeeklyGoalsData["composite"]
    resetInLabel?: string
    defaultTargets: Record<WeeklyGoalKey, number>
    isSkeleton: boolean
}

const Content = ({ items, composite, resetInLabel, defaultTargets, isSkeleton }: ContentProps) => {
    const summary = isSkeleton
        ? undefined
        : `${composite.percent}% complete (${composite.completed}/${composite.total} goals)${resetInLabel != null ? ` · ${resetInLabel}` : ""}`
    const gridItems: Array<StatGridCardItem> = items.map((item) => ({
        key: item.key,
        content: () => goalCellContent(item, defaultTargets, isSkeleton),
    }))
    return (
        <StackV
            principle="sibling-stack"
            explain="Same-kind peer stack — not group-boundary, because the summary and metric grid are repeating siblings in one card."
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Typography
                        size="sm"
                        weight="medium"
                        isSkeleton={isSkeleton}
                        text={summary}
                    />
                ),
                () => <StatGridCard items={gridItems} />,
            ]}
        />
    )
}

/**
 * "Weekly Goals" — the weekly-goal summary + six-metric breakdown. See the
 * file header for the full contract.
 *
 * @param props - {@link WeeklyGoalsProps}
 */
const WeeklyGoals = ({
    isLoading,
    error,
    onRetry,
    data,
    defaultTargets,
    isSkeleton = false,
}: WeeklyGoalsProps) => (
    <SurfaceCard
        identity={{ tier: "block", component: "WeeklyGoals" }}
        label="Weekly Goals"


        body={() => (
            <AsyncContent
                isLoading={isLoading}
                skeleton={() => (
                    <Content
                        items={loadingItems(defaultTargets)}
                        composite={{ percent: 0, completed: 0, total: 6 }}
                        defaultTargets={defaultTargets}
                        isSkeleton

                    />
                )}
                error={error}
                errorContent={{
                    title: "Couldn't load weekly goals",
                    description: "Retry to see the latest progress.",
                    onRetry,
                    retryLabel: "Retry",
                }}
                content={() => (data ? (
                    <Content
                        items={data.items}
                        composite={data.composite}
                        resetInLabel={data.resetInLabel}
                        defaultTargets={defaultTargets}
                        isSkeleton={isSkeleton}

                    />
                ) : null)}
            />
        )}
    />
)

export { WeeklyGoals }

import { SearchAutocomplete, type SearchAutocompleteItem } from "@/components/atoms/forms/SearchAutocomplete"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH } from "@/components/frames/Stack"

/**
 * BLOCK — `FoundationSearchBar`: the search row — debounced-typeahead field
 * left, a live match count right, one `StackH` seam apart. See the component
 * file header for why this is a SIBLING of `FoundationCategorySearchBar`
 * (not a reach past it) and for the independent-count-loading axis that makes
 * it a distinct block rather than the same one reused.
 *
 * 📐 ONE LEAF (§14d.2). `isSkeleton`, `isCountLoading`, an empty vs. populated
 * suggestion list, and every value `resultCount` can take (unknown / zero / N)
 * are all DATA on the same fixed structure — no node appears or disappears —
 * so they are STATES inside the single `Default` leaf, not leaves of their own.
 */

/** One autocomplete suggestion row (id + label only — the generic shape this bar needs). */
export interface FoundationSearchSuggestion {
    /** Stable id — the payload `onSelectSuggestion` fires with. */
    id: string
    /** Display label for the suggestion row. */
    label: string
}

/** Props for {@link FoundationSearchBar}. */
export interface FoundationSearchBarProps {
    /** Current text in the search field (controlled, debounced upstream by the screen). */
    query: string
    /** Fired with the new query on every keystroke. */
    onQueryChange: (query: string) => void
    /** Suggestions for the current query, best match first. */
    suggestions: Array<FoundationSearchSuggestion>
    /** Fired with the chosen suggestion's id. */
    onSelectSuggestion: (id: string) => void
    /** Placeholder for the empty field. Defaults to "Search...". */
    placeholder?: string
    /**
     * How many results the current query matched. `undefined` means the count
     * itself is not known yet (first paint, before the count read has ever
     * answered) — distinct from a real `0`, which renders.
     */
    resultCount?: number
    /**
     * `true` while the count is (re-)fetching on ITS OWN SWR read — independent
     * of `suggestions`/the field, which may already be interactive. Only the
     * count slot shimmers.
     */
    isCountLoading?: boolean
    /** Renders the field's + count's resting skeleton mirrors instead of the real controls. */
    isSkeleton?: boolean
}

/** Count wording — this block's own vocabulary, never handed in by the caller. */
const resultCountLabel = (count: number): string => (count === 0 ? "No documents yet" : `${count} documents`)

/**
 * The search row: typeahead field left, live match count right. See the file
 * header for why this is a sibling of `FoundationCategorySearchBar` rather
 * than a reach past it, and why the count's three data conditions stay one leaf.
 *
 * @param props - {@link FoundationSearchBarProps}
 */
const FoundationSearchBar = ({
    query,
    onQueryChange,
    suggestions,
    onSelectSuggestion,
    placeholder = "Search documents...",
    resultCount,
    isCountLoading = false,
    isSkeleton = false,
}: FoundationSearchBarProps) => {
    // Domain suggestion → the atom's generic item shape (no `description` line:
    // this bar's rows carry only a bare label).
    const items: Array<SearchAutocompleteItem> = suggestions.map((suggestion) => ({
        id: suggestion.id,
        label: suggestion.label,
    }))

    return (
        <StackH
            gap={3}
            justify="between"
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            isSkeleton={isSkeleton}
            identity={{ tier: "block", component: "FoundationSearchBar" }}
            items={[
                () => (
                    <SearchAutocomplete
                        items={items}
                        inputValue={query}
                        onInputChange={onQueryChange}
                        onSelect={onSelectSuggestion}
                        placeholder={placeholder}
                        isSkeleton={isSkeleton}
                    />
                ),
                ...(isSkeleton || isCountLoading
                    ? [
                        () => (
                            <Typography
                                size="sm"
                                color="muted"
                                isSkeleton
                            />
                        ),
                    ]
                    : resultCount !== undefined
                        ? [
                            () => (
                                <Typography
                                    size="sm"
                                    color="muted"
                                    tabularNums
                                    text={resultCountLabel(resultCount)}
                                />
                            ),
                        ]
                        : []),
            ]}
        />
    )
}

export { FoundationSearchBar }

import React from "react"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { CheckCircleIcon, CircleIcon, LockIcon, PlayCircleIcon } from "@phosphor-icons/react"
import { SurfaceCardList } from "@/components/composites/cards/SurfaceCard"
import { VariantChipDifficulty, type Difficulty } from "@/components/blocks/learn/VariantChip"
/**
 * `KeepGoingPath` — the continue-learning path for the current chapter, answering
 * "where am I + what's next". Deliberately does not redraw the full module tree
 * (that lives in the left rail). The block owns the shape — state icon
 * (play/check/circle), difficulty chip, lock — while the caller supplies only data.
 * Every variant shares one `SurfaceCardList` → rows tree, differing only in content.
 */
/** Learning state of a content item in the path. */
export type KeepGoingContentState = "done" | "active" | "todo"
/** A content item in the path — plain DATA, the block builds the shape itself. */
export interface KeepGoingContent {
    /** Stable React key. */
    id: string
    /** Content title. */
    title: string
    /** Reading time (minutes) — the block assembles it into the subtitle line. */
    minutes: number
    /** Done / in progress / not started — decides the leading icon. */
    state: KeepGoingContentState
    /** Difficulty — the block builds `VariantChipDifficulty` itself. */
    difficulty: Difficulty
    /** Content belongs to a paid tier → shows the lock mark. */
    locked?: boolean
    /** Row press handler. */
    onPress?: () => void
}
/**
 * Leading icon per state — the block owns this table, the caller doesn't pick.
 * Goes through `leading` (a node) rather than `leadingIcon`, because each state
 * carries its OWN COLOR while `leadingIcon` forces a shared `text-muted`.
 *
 * ALL THREE STATES SHARE ONE ROUND SHAPE: the in-progress
 * state uses `PlayCircleIcon` (a play mark INSIDE a circle) rather than a bare triangle
 * (`PlayIcon`) — its two siblings `CheckCircleIcon`/`CircleIcon` are both circles, so one
 * shape breaking the mould breaks the row's reading rhythm.
 *
 * `size-5` — the row's leading icon size (heading icon = 5;
 * the icon inside the chip follows the font instead).
 */
/** The leading mark one content state resolves to: which glyph, and how it is coloured. */
interface ContentLeadingStyle {
    /** Phosphor glyph component for this state. */
    Icon: typeof CircleIcon
    /** Size + colour classes; every state stays on one round shape (see the note above). */
    glyphClass: string
}
const CONTENT_LEADING: Record<KeepGoingContentState, ContentLeadingStyle> = {
    active: { Icon: PlayCircleIcon, glyphClass: "size-5 text-accent-soft-foreground" },
    done: { Icon: CheckCircleIcon, glyphClass: "size-5 text-success-soft-foreground" },
    todo: { Icon: CircleIcon, glyphClass: "size-5 text-foreground" },
}
/**
 * A LOCKED content item → the lock icon **REPLACES** the state icon at the head of
 * the row instead of hanging a second one on the tail.
 *
 * COLOR: `warning` — NOT muted. A muted lock turns
 * invisible, and this isn't decoration: it's a SALES DOOR, it has to be seen. Uses
 * the `-soft-foreground` step to match its siblings (accent/success), not a bold
 * `text-warning`.
 *
 * Why it sits at the HEAD of the row: a standard list row already has leading ·
 * title · subtitle · meta; bolting a second icon onto the tail just creates a spot
 * nobody reads. And semantically: for a not-yet-unlocked item, "read / reading /
 * unread" is meaningless — **the lock IS its state**.
 */
const LOCKED_LEADING = { Icon: LockIcon, glyphClass: "size-5 text-warning-soft-foreground" }
/**
 * The MODULE this path belongs to.
 *
 * A `string` prop cannot be checked: nothing stops a caller sending `"chapter 2-"` or a
 * completely different sentence. Two named fields make the wrong shape UNTYPEABLE.
 *
 * Declared as a NAMED, EXPORTED interface rather than inline `{ index: number; name:
 * string }`: an inline shape has no name to
 * import, so a caller building this object has nothing to type it against and every
 * call-site re-describes it by hand.
 */
export interface ModuleLike {
    /** 1-based position of the module inside the course. */
    index: number
    /** Module name WITHOUT any prefix — the block adds "Chapter"/"Continue" itself. */
    name: string
}
/** Props for {@link KeepGoingPath}. */
export interface KeepGoingPathBaseProps {
    /** The current module as an ENTITY — never a pre-baked string. See {@link ModuleLike}. */
    module: ModuleLike
    /** The content items in the continue-learning path. */
    contents: Array<KeepGoingContent>
    /**
     * `true` → mirror shimmer INSTEAD OF waiting on `contents`. The flag FLOWS
     * DOWN into `SurfaceCardList` (keeps the box/row/divider, only the text turns
     * to shimmer) and into `VariantChipDifficulty` — both the atom and the frame
     * already own their own `isSkeleton`.
     *
     * Empty while loading (`contents.length === 0`) → guesses **3** rows, matching
     * this pass's convention for repeating lists.
     *
     * NOTE: the leading icon (play/check/circle/lock) is chosen DIRECTLY by the block
     * itself from the `CONTENT_LEADING`/`LOCKED_LEADING` table — it doesn't go
     * through any atom — so this is exactly the §12c case that allows hand-rolling
     * ONE shimmer dot in place of the icon, instead of branching off to build a
     * whole separate row.
     */
    isSkeleton?: boolean
}
/** Placeholder DATA for the 3 guessed rows when `contents` is empty while loading (§12c). */
const SKELETON_ROWS: Array<KeepGoingContent> = Array.from({ length: 3 }, (_unused, index) => ({
    id: `skeleton-${index}`,
    title: "",
    minutes: 0,
    state: "todo",
    difficulty: "beginner",
}))
/**
 * Continue-learning path — module heading + content list, sharing its layout with
 * `LearnNudges`.
 *
 * @param props - {@link KeepGoingPathBaseProps}
 */
const KeepGoingPathBase = ({
    module,
    contents,
    isSkeleton = false,
}: KeepGoingPathBaseProps) => {
    // Empty while loading (no real contents yet) → guess 3 rows, keeping the right
    // shape for when real data arrives (§8). Once real `contents` exist, keep the
    // EXACT row count already there.
    const rows = isSkeleton && contents.length === 0 ? SKELETON_ROWS : contents
    return (
        <SurfaceCardList
            identity={{ tier: "block", component: "KeepGoingPath" }}
            // The heading sentence is assembled by the BLOCK — the caller only hands over the module name.
            // EVERY word of the heading is decided HERE — "Continue", "Chapter", the `·`.
            // The caller only supplies the number and the name.
            label={`Continue · Chapter ${module.index} · ${module.name}`}

            isSkeleton={isSkeleton}
            items={rows.map((content) => {
                // A lock REPLACES the state icon, it isn't added on top at the row's tail.
                const { Icon, glyphClass } = content.locked
                    ? LOCKED_LEADING
                    : CONTENT_LEADING[content.state]
                return {
                    key: content.id,
                    leading: isSkeleton ? (
                        // The icon is chosen DIRECTLY by the block itself (no atom in between) —
                        // hand-roll a single shimmer dot in place of the state/lock icon.
                        () => <Skeleton className="size-5 shrink-0 rounded-full" />
                    ) : (
                        () => (
                            <Icon
                                aria-label={content.locked ? "Paid content" : undefined}
                                aria-hidden={content.locked ? undefined : true}
                                focusable="false"
                                className={glyphClass}
                            />
                        )
                    ),
                    title: content.title,
                    subtitle: `${content.minutes} min read`,
                    onPress: content.onPress,
                    // Meta now holds EXACTLY ONE thing: difficulty. The shape is owned by
